def crear_plantilla_inicial(apps, schema_editor):
    """Cada empresa arranca con la plantilla de cotización de autos que ya usaba Gali (sin cuenta ni CC: se configuran)."""
    PlantillaCorreo = apps.get_model('policies', 'PlantillaCorreo')
    if not PlantillaCorreo.objects.exists():
        PlantillaCorreo.objects.create(
            nombre='Cotización de autos', tipo_seguro='autos', para='{correo_cliente}',
            asunto='{placa} {cliente_mayusculas} COTIZACIÓN PÓLIZA DE AUTO', cuerpo=CUERPO_INICIAL, predeterminada=True)


